begin;
alter table public.ft_member_settings add column if not exists calorie_goal integer not null default 2000 check(calorie_goal between 500 and 10000),add column if not exists protein_goal_g integer not null default 120 check(protein_goal_g between 0 and 1000),add column if not exists carb_goal_g integer not null default 200 check(carb_goal_g between 0 and 1500),add column if not exists fat_goal_g integer not null default 70 check(fat_goal_g between 0 and 500);
create table if not exists public.ft_food_logs(id uuid primary key default gen_random_uuid(),household_id uuid not null,user_id uuid not null,logged_on date not null default current_date,meal text not null default 'meal' check(meal in('breakfast','lunch','dinner','snack','meal')),food_name text not null,source text not null default 'USDA',source_id text,serving_label text,quantity numeric(6,2) not null default 1 check(quantity>0),calories numeric(8,1) not null default 0,protein_g numeric(8,1) not null default 0,carbs_g numeric(8,1) not null default 0,fat_g numeric(8,1) not null default 0,created_at timestamptz not null default now(),foreign key(household_id,user_id) references public.ft_household_members(household_id,user_id) on delete cascade);
alter table public.ft_food_logs enable row level security;
create policy ft_food_logs_self on public.ft_food_logs for all to authenticated using(user_id=auth.uid() and public.ft_is_household_member(household_id)) with check(user_id=auth.uid() and public.ft_is_household_member(household_id));
grant select,insert,update,delete on public.ft_food_logs to authenticated;
create table if not exists public.ft_water_logs(id uuid primary key default gen_random_uuid(),household_id uuid not null,user_id uuid not null,logged_on date not null default current_date,ounces integer not null check(ounces between 1 and 200),created_at timestamptz not null default now(),foreign key(household_id,user_id) references public.ft_household_members(household_id,user_id) on delete cascade);
alter table public.ft_water_logs enable row level security;
create policy ft_water_logs_self on public.ft_water_logs for all to authenticated using(user_id=auth.uid() and public.ft_is_household_member(household_id)) with check(user_id=auth.uid() and public.ft_is_household_member(household_id));
grant select,insert,update,delete on public.ft_water_logs to authenticated;
commit;
